#include <stddef.h>

/* Keep call boundaries to distinguish summaries from textual inlining. */
static __attribute__((noinline)) unsigned layer8(unsigned k) { return k * 3U + 7U; }
static __attribute__((noinline)) unsigned layer5(unsigned k) { return layer8(k); }
static __attribute__((noinline)) unsigned layer3(unsigned k) { return layer5(k); }

void stable_chain(unsigned *out, const unsigned *input, size_t n, unsigned k) {
    for (size_t i = 0; i < n; ++i) out[i] = input[i] + layer3(k);
}

static __attribute__((noinline)) unsigned read_parameter(const unsigned *p) { return *p; }
static __attribute__((noinline)) void write_parameter(unsigned *p) { *p += 1U; }

void changing_referent(unsigned *out, size_t n, unsigned *p) {
    for (size_t i = 0; i < n; ++i) {
        out[i] = read_parameter(p);
        write_parameter(p);
    }
}

extern unsigned opaque(unsigned k);
void unknown_callee(unsigned *out, size_t n, unsigned k) {
    for (size_t i = 0; i < n; ++i) out[i] = opaque(k);
}
